SET local check_function_bodies = off;

CREATE TABLE "public"."document_parsing_jobs" (
  "id"           bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "document_id"  bigint,
  "status"       text                     DEFAULT 'pending'::text,
  "error"        text,
  "started_at"   timestamp with time zone,
  "completed_at" timestamp with time zone,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "document_parsing_jobs_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."document_parsing_jobs"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."documents" (
  "id"              bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."project_documents_id_seq") NOT NULL,
  "project_id"      uuid,
  "file_name"       text                     NOT NULL,
  "storage_path"    text                     NOT NULL,
  "md_storage_path" text,
  "doc_id"          text,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "org_id"          uuid,
  "mime_type"       text,
  "file_size"       numeric,
  CONSTRAINT "project_documents_pkey" PRIMARY KEY (id),
  "uploaded_by"     uuid                     DEFAULT auth.uid()
);

ALTER TABLE "public"."documents"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."observations" (
  "id"                      bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "screening_id"            bigint,
  "schema_field_id"         bigint,
  "document_id"             bigint,
  "observation_type"        text,
  "confidence"              numeric,
  "score_impact"            numeric,
  "created_at"              timestamp with time zone NOT NULL DEFAULT now(),
  "name"                    text,
  "observation_description" text,
  "gap_description"         text,
  "source_reference"        text,
  "is_gap"                  boolean,
  CONSTRAINT "observations_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."observations"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."org_user" (
  "org_id"  uuid NOT NULL,
  "user_id" uuid NOT NULL,
  CONSTRAINT "org_user_pkey" PRIMARY KEY (org_id, user_id)
);

ALTER TABLE "public"."org_user"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."organisations" (
  "id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "name"       text                     NOT NULL,
  "slug"       text,
  CONSTRAINT "organisations_pkey" PRIMARY KEY (id),
  CONSTRAINT "organisations_slug_key" UNIQUE (slug)
);

ALTER TABLE "public"."organisations"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."profiles" (
  "id"          uuid                     NOT NULL,
  "updated_at"  timestamp with time zone,
  "username"    text,
  "full_name"   text,
  "avatar_url"  text,
  "website"     text,
  "last_org_id" uuid,
  "email"       text,
  CONSTRAINT "profiles_pkey" PRIMARY KEY (id),
  CONSTRAINT "profiles_username_key" UNIQUE (username),
  CONSTRAINT "username_length" CHECK ((char_length(username) >= 3))
);

ALTER TABLE "public"."profiles"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."projects" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "name"            text,
  "status"          text,
  "screening_score" double precision,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "org_id"          uuid                     NOT NULL,
  CONSTRAINT "projects_pkey" PRIMARY KEY (id),
  "created_by"      uuid                     DEFAULT auth.uid()
);

ALTER TABLE "public"."projects"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."schema_categories" (
  "id"            bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "template_id"   bigint,
  "code"          text,
  "name"          text                     NOT NULL,
  "weight"        numeric,
  "display_order" double precision,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "description"   text,
  CONSTRAINT "schema_categories_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."schema_categories"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."schema_field" (
  "id"                     bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "category_id"            bigint,
  "semantic_id"            text,
  "is_required"            boolean,
  "weight"                 numeric,
  "extraction_description" text,
  "gap_description"        text,
  "display_order"          double precision,
  "created_at"             timestamp with time zone NOT NULL DEFAULT now(),
  "is_dealbreaker"         boolean,
  "created_by"             uuid,
  "name"                   text                     NOT NULL,
  CONSTRAINT "schema_field_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."schema_field"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."schema_templates" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name"        text,
  "org_id"      uuid,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "description" text,
  "updated_at"  timestamp with time zone,
  CONSTRAINT "schema_templates_pkey" PRIMARY KEY (id),
  "created_by"  uuid                     DEFAULT auth.uid()
);

ALTER TABLE "public"."schema_templates"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."screening_documents" (
  "screening_id" bigint                   NOT NULL,
  "document_id"  bigint                   NOT NULL,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "screening_documents_pkey" PRIMARY KEY (screening_id, document_id)
);

ALTER TABLE "public"."screening_documents"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."screenings" (
  "id"                 bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "project_id"         uuid,
  "schema_template_id" bigint,
  "started_at"         timestamp with time zone,
  "ended_at"           timestamp with time zone,
  "created_by"         uuid,
  "created_at"         timestamp with time zone NOT NULL DEFAULT now(),
  "name"               text,
  CONSTRAINT "screenings_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."screenings"
  ENABLE ROW LEVEL SECURITY;

CREATE TYPE "public"."org_member_role" AS ENUM (
  'owner',
  'admin',
  'member'
);

ALTER TABLE "public"."org_user"
  ADD COLUMN "role" public.org_member_role NOT NULL DEFAULT 'member'::public.org_member_role;

ALTER TABLE "public"."org_user"
  ADD COLUMN "created_at" timestamp WITH time zone NOT NULL DEFAULT now();

CREATE OR REPLACE FUNCTION public.create_project (
  p_org_id uuid,
  p_name   text
)
  RETURNS TABLE (
    project_id     uuid,
    project_name   text,
    status         text,
    created_at     timestamp with time zone,
    creator_id     uuid,
    creator_name   text,
    creator_avatar text
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.org_user
    WHERE org_id = p_org_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  INSERT INTO public.projects (org_id, name, created_by)
  VALUES (p_org_id, p_name, auth.uid())
  RETURNING
    id,
    name,
    status,
    created_at,
    auth.uid(),
    (SELECT full_name  FROM public.profiles WHERE id = auth.uid()),
    (SELECT avatar_url FROM public.profiles WHERE id = auth.uid());
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_schema_category (
  p_name        text,
  p_template_id bigint,
  p_description text,
  p_weight      numeric
)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
DECLARE
  v_next_order  double precision;
  v_new_id      bigint;
  v_org_id      uuid;
BEGIN
  SELECT org_id INTO v_org_id
  FROM public.schema_templates
  WHERE id = p_template_id;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Template not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.org_user
    WHERE org_id = v_org_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Beregn næste display_order for templaten
  SELECT COALESCE(MAX(display_order), 0) + 1
  INTO  v_next_order
  FROM  public.schema_categories
  WHERE template_id = p_template_id;

  INSERT INTO public.schema_categories
    (template_id, name, description, display_order, weight)
  VALUES
    (p_template_id, p_name, p_description, v_next_order, p_weight)
  RETURNING id INTO v_new_id;

  RETURN v_new_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_schema_field (
  p_category_id            bigint,
  p_name                   text,
  p_semantic_id            text,
  p_is_required            boolean          DEFAULT false,
  p_weight                 numeric          DEFAULT 1.0,
  p_extraction_description text             DEFAULT NULL::text,
  p_gap_description        text             DEFAULT NULL::text,
  p_display_order          double precision DEFAULT NULL::double precision,
  p_is_dealbreaker         boolean          DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
DECLARE
  v_new_id        bigint;
  v_org_id        uuid;
  v_display_order double precision;
BEGIN

  -- Verificer at kategorien eksisterer og tilhører brugerens org
  SELECT st.org_id
  INTO v_org_id
  FROM schema_categories sc
  JOIN schema_templates st ON st.id = sc.template_id
  WHERE sc.id = p_category_id;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Category not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM org_user
    WHERE org_id = v_org_id
      AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Tilføj til sidst hvis display_order ikke er angivet
  IF p_display_order IS NULL THEN
    SELECT COALESCE(MAX(display_order), 0) + 1
    INTO v_display_order
    FROM schema_field
    WHERE category_id = p_category_id;
  ELSE
    v_display_order := p_display_order;
  END IF;

  INSERT INTO schema_field (
    category_id,
    name,
    semantic_id,
    is_required,
    weight,
    extraction_description,
    gap_description,
    display_order,
    is_dealbreaker,
    created_by
  )
  VALUES (
    p_category_id,
    p_name,
    p_semantic_id,
    p_is_required,
    p_weight,
    p_extraction_description,
    p_gap_description,
    v_display_order,
    p_is_dealbreaker,
    auth.uid()
  )
  RETURNING id INTO v_new_id;

  RETURN (
    SELECT jsonb_build_object(
      'id',                     sf.id,
      'category_id',            sf.category_id,
      'name',                   sf.name,
      'semantic_id',            sf.semantic_id,
      'is_required',            sf.is_required,
      'weight',                 sf.weight,
      'extraction_description', sf.extraction_description,
      'gap_description',        sf.gap_description,
      'display_order',          sf.display_order,
      'is_dealbreaker',         sf.is_dealbreaker,
      'created_by',             sf.created_by,
      'created_at',             sf.created_at
    )
    FROM schema_field sf
    WHERE sf.id = v_new_id
  );

END;
$function$;

CREATE OR REPLACE FUNCTION public.create_screening (
  p_project_id   uuid,
  p_template_id  bigint,
  p_document_ids bigint[]
)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
DECLARE
  v_screening_id bigint;
  v_org_id       uuid;
BEGIN
  SELECT org_id INTO v_org_id
  FROM public.projects
  WHERE id = p_project_id;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Project not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.org_user
    WHERE org_id = v_org_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  INSERT INTO public.screenings (
    project_id,
    schema_template_id,
    created_by
  )
  VALUES (
    p_project_id,
    p_template_id,
    auth.uid()
  )
  RETURNING id INTO v_screening_id;

  INSERT INTO public.screening_documents (screening_id, document_id)
  SELECT v_screening_id, UNNEST(p_document_ids);

  RETURN v_screening_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_active_org_id()
  RETURNS uuid
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_org_id uuid;
begin
  select last_org_id into v_org_id
  from public.profiles
  where id = (select auth.uid());

  if v_org_id is null then
    raise exception 'No active organisation for user %', (select auth.uid());
  end if;

  -- Verificer at brugeren stadig er aktiv i organisationen
  if not exists (
    select 1 from public.org_user
    where org_id  = v_org_id
      and user_id = (select auth.uid())
  ) then
    raise exception 'User % is no longer a member of their active organisation',
      (select auth.uid());
  end if;

  return v_org_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_current_user_org()
  RETURNS TABLE (
    user_id     uuid,
    full_name   text,
    email       text,
    role        public.org_member_role,
    last_org_id uuid,
    org         jsonb
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
  select
    profile.id,
    profile.full_name,
    auth_user.email,
    membership.role,
    profile.last_org_id,
    jsonb_build_object(
      'id',   org.id,
      'name', org.name,
      'slug', org.slug
    )
  from public.profiles        profile
  join auth.users             auth_user  on auth_user.id       = profile.id
  join public.org_user        membership on membership.user_id = profile.id
  join public.organisations   org        on org.id             = membership.org_id
  where profile.id = auth.uid()
  order by
    case when membership.org_id = profile.last_org_id then 0 else 1 end,
    membership.created_at desc
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.get_org_dashboard_overview (
  p_org_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$DECLARE
  v_result jsonb;
BEGIN

  WITH screening_agg AS (
    SELECT
      s.project_id,
      COUNT(s.id)                                                    AS total_screenings,
      COUNT(s.id) FILTER (WHERE s.started_at IS NOT NULL
                            AND s.ended_at IS NULL)                  AS active_screenings,
      COUNT(s.id) FILTER (WHERE s.ended_at IS NOT NULL)              AS completed_screenings
    FROM public.screenings s
    JOIN public.projects p ON p.id = s.project_id
    WHERE p.org_id = p_org_id
    GROUP BY s.project_id
  ),

  latest_screening AS (
    SELECT DISTINCT ON (s.project_id)
      s.project_id,
      s.id          AS latest_screening_id,
      s.name        AS latest_screening_name,
      s.started_at  AS latest_screening_started_at,
      s.ended_at    AS latest_screening_ended_at
    FROM public.screenings s
    JOIN public.projects p ON p.id = s.project_id
    WHERE p.org_id = p_org_id
    ORDER BY s.project_id, s.created_at DESC
  ),

  doc_count AS (
    SELECT
      d.project_id,
      COUNT(DISTINCT d.id) AS total_documents
    FROM public.documents d
    JOIN public.projects p ON p.id = d.project_id
    WHERE p.org_id = p_org_id
    GROUP BY d.project_id
  ),

  -- Org-wide totaler aggregeret i én CTE for at undgå at joine rå documents-tabel
  org_totals AS (
    SELECT
      COUNT(DISTINCT p.id)                                           AS total_projects,
      COALESCE(SUM(dc.total_documents), 0)                           AS total_documents,
      COALESCE(SUM(sa.active_screenings), 0)                         AS total_active_screenings,
      COALESCE(SUM(sa.completed_screenings), 0)                      AS total_completed_screenings
    FROM public.projects p
    LEFT JOIN doc_count dc      ON dc.project_id = p.id
    LEFT JOIN screening_agg sa  ON sa.project_id = p.id
    WHERE p.org_id = p_org_id
  )

  SELECT jsonb_build_object(

    'widgets', jsonb_build_object(
      'total_projects',             (SELECT total_projects           FROM org_totals),
      'total_documents',            (SELECT total_documents          FROM org_totals),
      'total_active_screenings',    (SELECT total_active_screenings  FROM org_totals),
      'total_completed_screenings', (SELECT total_completed_screenings FROM org_totals)
    ),

    'projects', (
      SELECT jsonb_agg(
        jsonb_build_object(
          'project_id',                   p.id,
          'project_name',                 p.name,
          'project_status',               p.status,
          'screening_score',              p.screening_score,
          'created_at',                   p.created_at,
          'created_by',                   pr.full_name,
          'total_screenings',             COALESCE(sa.total_screenings, 0),
          'active_screenings',            COALESCE(sa.active_screenings, 0),
          'completed_screenings',         COALESCE(sa.completed_screenings, 0),
          'latest_screening_id',          ls.latest_screening_id,
          'latest_screening_name',        ls.latest_screening_name,
          'latest_screening_started_at',  ls.latest_screening_started_at,
          'latest_screening_ended_at',    ls.latest_screening_ended_at,
          'total_documents',              COALESCE(dc.total_documents, 0)
        )
        ORDER BY p.created_at DESC
      )
      FROM public.projects p
      LEFT JOIN public.profiles pr  ON pr.id = p.created_by
      LEFT JOIN screening_agg sa    ON sa.project_id = p.id
      LEFT JOIN latest_screening ls ON ls.project_id = p.id
      LEFT JOIN doc_count dc        ON dc.project_id = p.id
      WHERE p.org_id = p_org_id
    )

  ) INTO v_result;

  RETURN v_result;
END;$function$;

CREATE OR REPLACE FUNCTION public.get_org_schema_templates (
  p_org_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
BEGIN
  RETURN (
    WITH template_counts AS (
      SELECT
        st.id,
        st.name,
        st.description,
        st.created_at,
        st.updated_at,
        st.created_by,
        COUNT(DISTINCT sc.id) AS category_count,
        COUNT(DISTINCT sf.id) AS field_count
      FROM public.schema_templates st
      LEFT JOIN public.schema_categories sc ON sc.template_id = st.id
      LEFT JOIN public.schema_field sf      ON sf.category_id = sc.id
      WHERE st.org_id = p_org_id
      GROUP BY st.id, st.name, st.description, st.created_at, st.updated_at, st.created_by
    )
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id',             tc.id,
        'name',           tc.name,
        'description',    tc.description,
        'created_at',     tc.created_at,
        'updated_at',     tc.updated_at,
        'category_count', tc.category_count,
        'field_count',    tc.field_count,
        'creator',        (
                            SELECT row_to_json(profile_data)
                            FROM get_profile(tc.created_by) AS profile_data
                          )
      )
      ORDER BY tc.created_at DESC
    ), '[]'::jsonb)
    FROM template_counts tc
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_organisation_screenings (
  p_org_id uuid
)
  RETURNS TABLE (
    screening_id         bigint,
    screening_created_at timestamp with time zone,
    started_at           timestamp with time zone,
    ended_at             timestamp with time zone,
    project_id           uuid,
    project_name         text,
    project_status       text,
    project_score        double precision,
    template_id          bigint,
    template_name        text,
    document_count       bigint,
    created_by_name      text
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
  SELECT
    s.id                    AS screening_id,
    s.created_at            AS screening_created_at,
    s.started_at,
    s.ended_at,
    p.id                    AS project_id,
    p.name                  AS project_name,
    p.status                AS project_status,
    p.screening_score       AS project_score,
    st.id                   AS template_id,
    st.name                 AS template_name,
    COUNT(sd.document_id)   AS document_count,
    pr.full_name            AS created_by_name
  FROM public.screenings s
  JOIN public.projects p
    ON p.id = s.project_id
  LEFT JOIN public.schema_templates st
    ON st.id = s.schema_template_id
  LEFT JOIN public.screening_documents sd
    ON sd.screening_id = s.id
  LEFT JOIN public.profiles pr
    ON pr.id = s.created_by
  WHERE p.org_id = p_org_id
  GROUP BY
    s.id, s.created_at, s.started_at, s.ended_at,
    p.id, p.name, p.status, p.screening_score,
    st.id, st.name,
    pr.full_name
  ORDER BY s.created_at DESC;
$function$;

CREATE OR REPLACE FUNCTION public.get_profile (
  p_user_id uuid
)
  RETURNS TABLE (
    user_id    uuid,
    full_name  text,
    avatar_url text,
    email      text
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
  select
    profile.id,
    profile.full_name,
    profile.avatar_url,
    auth_user.email
  from public.profiles  profile
  join auth.users       auth_user on auth_user.id = profile.id
  where profile.id = p_user_id;
$function$;

CREATE OR REPLACE FUNCTION public.get_project_details (
  p_project_id uuid
)
  RETURNS json
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
DECLARE
  v_result json;
BEGIN
  SELECT json_build_object(

    -- Projektinfo
    'project', (
      SELECT json_build_object(
        'id',               p.id,
        'name',             p.name,
        'status',           p.status,
        'screening_score',  p.screening_score,
        'created_at',       p.created_at,
        'created_by',       json_build_object(
                              'id',        pr.id,
                              'full_name', pr.full_name,
                              'email',     pr.email,
                              'avatar_url',pr.avatar_url
                            )
      )
      FROM public.projects p
      LEFT JOIN public.profiles pr ON pr.id = p.created_by
      WHERE p.id = p_project_id
    ),

    -- Dokumenter med parsing-status
    'documents', (
      SELECT COALESCE(json_agg(
        json_build_object(
          'id',           d.id,
          'file_name',    d.file_name,
          'mime_type',    d.mime_type,
          'file_size',    d.file_size,
          'created_at',   d.created_at,
          'uploaded_by',  json_build_object(
                            'id',        pr.id,
                            'full_name', pr.full_name,
                            'avatar_url',pr.avatar_url
                          ),
          'parsing_job',  (
            SELECT json_build_object(
              'status',       pj.status,
              'started_at',   pj.started_at,
              'completed_at', pj.completed_at,
              'error',        pj.error
            )
            FROM public.document_parsing_jobs pj
            WHERE pj.document_id = d.id
            ORDER BY pj.created_at DESC
            LIMIT 1
          )
        )
        ORDER BY d.created_at DESC
      ), '[]'::json)
      FROM public.documents d
      LEFT JOIN public.profiles pr ON pr.id = d.uploaded_by
      WHERE d.project_id = p_project_id
    ),

    -- Dokument-statistik
    'document_stats', (
      SELECT json_build_object(
        'total_count',    COUNT(*),
        'total_size',     COALESCE(SUM(d.file_size), 0),
        'parsed_count',   COUNT(pj.id) FILTER (
                            WHERE pj.status = 'completed'
                          ),
        'pending_count',  COUNT(pj.id) FILTER (
                            WHERE pj.status = 'pending' OR pj.status IS NULL
                          ),
        'failed_count',   COUNT(pj.id) FILTER (
                            WHERE pj.status = 'failed'
                          )
      )
      FROM public.documents d
      LEFT JOIN public.document_parsing_jobs pj
        ON pj.document_id = d.id
        AND pj.id = (
          SELECT id FROM public.document_parsing_jobs
          WHERE document_id = d.id
          ORDER BY created_at DESC LIMIT 1
        )
      WHERE d.project_id = p_project_id
    ),

    -- Screeninger med template og observations-tælling
    'screenings', (
      SELECT COALESCE(json_agg(
        json_build_object(
          'id',                 s.id,
          'name',               s.name,
          'started_at',         s.started_at,
          'ended_at',           s.ended_at,
          'created_at',         s.created_at,
          'is_completed',       s.ended_at IS NOT NULL,
          'schema_template',    json_build_object(
                                  'id',          st.id,
                                  'name',        st.name,
                                  'description', st.description
                                ),
          'document_count',     (
            SELECT COUNT(*) FROM public.screening_documents sd
            WHERE sd.screening_id = s.id
          ),
          'observation_count',  (
            SELECT COUNT(*) FROM public.observations o
            WHERE o.screening_id = s.id
          ),
          'gap_count',          (
            SELECT COUNT(*) FROM public.observations o
            WHERE o.screening_id = s.id AND o.is_gap = true
          ),
          'created_by',         json_build_object(
                                  'id',        pr.id,
                                  'full_name', pr.full_name,
                                  'avatar_url',pr.avatar_url
                                )
        )
        ORDER BY s.created_at DESC
      ), '[]'::json)
      FROM public.screenings s
      LEFT JOIN public.schema_templates st ON st.id = s.schema_template_id
      LEFT JOIN public.profiles pr ON pr.id = s.created_by
      WHERE s.project_id = p_project_id
    ),

    -- Screening-statistik
    'screening_stats', (
      SELECT json_build_object(
        'total_count',     COUNT(*),
        'completed_count', COUNT(*) FILTER (WHERE s.ended_at IS NOT NULL),
        'in_progress_count', COUNT(*) FILTER (WHERE s.started_at IS NOT NULL AND s.ended_at IS NULL),
        'total_gaps',      (
          SELECT COUNT(*) FROM public.observations o
          JOIN public.screenings s2 ON s2.id = o.screening_id
          WHERE s2.project_id = p_project_id AND o.is_gap = true
        ),
        'total_observations', (
          SELECT COUNT(*) FROM public.observations o
          JOIN public.screenings s2 ON s2.id = o.screening_id
          WHERE s2.project_id = p_project_id
        )
      )
      FROM public.screenings s
      WHERE s.project_id = p_project_id
    )

  ) INTO v_result;

  RETURN v_result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_project_documents (
  p_project_id uuid
)
  RETURNS TABLE (
    id                   bigint,
    file_name            text,
    storage_path         text,
    md_storage_path      text,
    doc_id               text,
    mime_type            text,
    file_size            numeric,
    uploaded_by          uuid,
    org_id               uuid,
    created_at           timestamp with time zone,
    parsing_status       text,
    parsing_error        text,
    parsing_started_at   timestamp with time zone,
    parsing_completed_at timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
  SELECT
    d.id,
    d.file_name,
    d.storage_path,
    d.md_storage_path,
    d.doc_id,
    d.mime_type,
    d.file_size,
    d.uploaded_by,
    d.org_id,
    d.created_at,
    -- Seneste parsing-job per dokument via lateral join
    pj.status        AS parsing_status,
    pj.error         AS parsing_error,
    pj.started_at    AS parsing_started_at,
    pj.completed_at  AS parsing_completed_at
  FROM public.documents d
  LEFT JOIN LATERAL (
    SELECT status, error, started_at, completed_at
    FROM public.document_parsing_jobs
    WHERE document_id = d.id
    ORDER BY created_at DESC
    LIMIT 1
  ) pj ON true
  WHERE d.project_id = p_project_id
  ORDER BY d.created_at DESC;
$function$;

CREATE OR REPLACE FUNCTION public.get_projects (
  p_org_id uuid
)
  RETURNS TABLE (
    project_id        uuid,
    project_name      text,
    status            text,
    screening_score   double precision,
    created_at        timestamp with time zone,
    creator_id        uuid,
    creator_name      text,
    creator_avatar    text,
    screening_count   bigint,
    document_count    bigint,
    last_screening_at timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
  select
    project.id,
    project.name,
    project.status,
    project.screening_score,
    project.created_at,
    creator.user_id,
    creator.full_name,
    creator.avatar_url,
    count(distinct screening.id)  as screening_count,
    count(distinct document.id)   as document_count,
    max(screening.created_at)     as last_screening_at
  from public.projects  project
  left join lateral (
    select * from public.get_profile(project.created_by)
  ) creator on true
  left join public.screenings  screening on screening.project_id = project.id
  left join public.documents   document  on document.project_id  = project.id
  where project.org_id = p_org_id
  group by
    project.id,
    project.name,
    project.status,
    project.screening_score,
    project.created_at,
    creator.user_id,
    creator.full_name,
    creator.avatar_url;
$function$;

CREATE OR REPLACE FUNCTION public.get_schema_categories (
  p_template_id bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
DECLARE
  v_org_id uuid;
BEGIN

  -- Verificer at templaten eksisterer og tilhører brugerens org
  SELECT org_id
  INTO v_org_id
  FROM schema_templates
  WHERE id = p_template_id;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Template not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM org_user
    WHERE org_id = v_org_id
      AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN (
    SELECT jsonb_agg(
      jsonb_build_object(
        'id',            sc.id,
        'template_id',   sc.template_id,
        'code',          sc.code,
        'name',          sc.name,
        'weight',        sc.weight,
        'display_order', sc.display_order,
        'description',   sc.description,
        'created_at',    sc.created_at
      )
      ORDER BY sc.display_order ASC NULLS LAST
    )
    FROM schema_categories sc
    WHERE sc.template_id = p_template_id
  );

END;
$function$;

CREATE OR REPLACE FUNCTION public.get_schema_template (
  p_template_id bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
DECLARE
  v_result jsonb;
BEGIN

  IF NOT EXISTS (
    SELECT 1
    FROM schema_templates st
    JOIN org_user ou ON ou.org_id = st.org_id
    WHERE st.id = p_template_id
      AND ou.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Template not found or access denied';
  END IF;

  SELECT jsonb_build_object(
    'id',          st.id,
    'name',        st.name,
    'description', st.description,
    'org_id',      st.org_id,
    'created_by',  st.created_by,
    'created_at',  st.created_at,
    'updated_at',  st.updated_at,
    'categories',  COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id',            sc.id,
            'code',          sc.code,
            'name',          sc.name,
            'description',   sc.description,
            'weight',        sc.weight,
            'display_order', sc.display_order,
            'created_at',    sc.created_at,
            'fields',        COALESCE(
              (
                SELECT jsonb_agg(
                  jsonb_build_object(
                    'id',                     sf.id,
                    'semantic_id',            sf.semantic_id,
                    'name',                   sf.name,
                    'is_required',            sf.is_required,
                    'is_dealbreaker',         sf.is_dealbreaker,
                    'weight',                 sf.weight,
                    'extraction_description', sf.extraction_description,
                    'gap_description',        sf.gap_description,
                    'display_order',          sf.display_order,
                    'created_by',             sf.created_by,
                    'created_at',             sf.created_at
                  )
                  ORDER BY sf.display_order ASC NULLS LAST
                )
                FROM schema_field sf
                WHERE sf.category_id = sc.id
              ),
              '[]'::jsonb
            )
          )
          ORDER BY sc.display_order ASC NULLS LAST
        )
        FROM schema_categories sc
        WHERE sc.template_id = st.id
      ),
      '[]'::jsonb
    )
  )
  INTO v_result
  FROM schema_templates st
  WHERE st.id = p_template_id;

  RETURN v_result;

END;
$function$;

CREATE OR REPLACE FUNCTION public.get_screening_details (
  p_screening_id bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$DECLARE
  v_result jsonb;
  v_summary jsonb;
  v_total_weight numeric;
BEGIN
  -- Total possible weight for normalisering af score_drag_pct
  SELECT COALESCE(SUM(sf.weight * sc.weight), 0)
  INTO v_total_weight
  FROM public.observations o
  JOIN public.schema_field sf      ON sf.id = o.schema_field_id
  JOIN public.schema_categories sc ON sc.id = sf.category_id
  WHERE o.screening_id = p_screening_id;

  -- Summary separat
  SELECT jsonb_build_object(
    'total_observations', COUNT(o.id),
    'gap_count',          COUNT(o.id) FILTER (WHERE o.is_gap = TRUE),
    'dealbreaker_count',  COUNT(o.id) FILTER (WHERE o.is_gap = TRUE AND sf.is_dealbreaker = TRUE),
    'mavt_score',         ROUND(
                            SUM(((o.score_impact + 2.0) / 4.0) * sf.weight * sc.weight)
                            / NULLIF(SUM(sf.weight * sc.weight), 0)
                          , 2),
    'rag_status',         CASE
                            WHEN SUM(((o.score_impact + 2.0) / 4.0) * sf.weight * sc.weight)
                                 / NULLIF(SUM(sf.weight * sc.weight), 0) < 0.40 THEN 'red'
                            WHEN SUM(((o.score_impact + 2.0) / 4.0) * sf.weight * sc.weight)
                                 / NULLIF(SUM(sf.weight * sc.weight), 0) < 0.65 THEN 'amber'
                            ELSE 'green'
                          END,
    'distribution',       jsonb_build_object(
                            'pct_red',     ROUND(
                                             SUM(sf.weight * sc.weight) FILTER (WHERE o.score_impact <= -2)
                                             / NULLIF(SUM(sf.weight * sc.weight), 0) * 100
                                           , 1),
                            'pct_amber',   ROUND(
                                             SUM(sf.weight * sc.weight) FILTER (WHERE o.score_impact = -1)
                                             / NULLIF(SUM(sf.weight * sc.weight), 0) * 100
                                           , 1),
                            'pct_neutral', ROUND(
                                             SUM(sf.weight * sc.weight) FILTER (WHERE o.score_impact = 0)
                                             / NULLIF(SUM(sf.weight * sc.weight), 0) * 100
                                           , 1),
                            'pct_green',   ROUND(
                                             SUM(sf.weight * sc.weight) FILTER (WHERE o.score_impact >= 1)
                                             / NULLIF(SUM(sf.weight * sc.weight), 0) * 100
                                           , 1)
                          )
  )
  INTO v_summary
  FROM public.observations o
  JOIN public.schema_field sf      ON sf.id = o.schema_field_id
  JOIN public.schema_categories sc ON sc.id = sf.category_id
  WHERE o.screening_id = p_screening_id;

  SELECT jsonb_build_object(
    'summary', v_summary,

    'screening', jsonb_build_object(
      'id',         s.id,
      'name',       s.name,
      'created_at', s.created_at,
      'started_at', s.started_at,
      'ended_at',   s.ended_at,
      'created_by', s.created_by,

      'project', jsonb_build_object(
        'id',              p.id,
        'name',            p.name,
        'status',          p.status,
        'screening_score', p.screening_score
      ),

      'template', jsonb_build_object(
        'id',          st.id,
        'name',        st.name,
        'description', st.description
      ),

      'documents', (
        SELECT jsonb_agg(jsonb_build_object(
          'id',              d.id,
          'file_name',       d.file_name,
          'mime_type',       d.mime_type,
          'file_size',       d.file_size,
          'storage_path',    d.storage_path,
          'md_storage_path', d.md_storage_path,
          'doc_id',          d.doc_id,
          'created_at',      d.created_at
        ))
        FROM public.screening_documents sd
        JOIN public.documents d ON d.id = sd.document_id
        WHERE sd.screening_id = s.id
      )
    ),

    'categories', (
      SELECT jsonb_agg(
        jsonb_build_object(
          'id',            cat.id,
          'code',          cat.code,
          'name',          cat.name,
          'description',   cat.description,
          'weight',        cat.weight,
          'display_order', cat.display_order,

          -- RAG og score aggregeret per kategori
          'category_mavt_score', (
            SELECT ROUND(
              SUM(((o.score_impact + 2.0) / 4.0) * sf.weight * cat.weight)
              / NULLIF(SUM(sf.weight * cat.weight), 0)
            , 2)
            FROM public.observations o
            JOIN public.schema_field sf ON sf.id = o.schema_field_id
            WHERE o.screening_id = p_screening_id
              AND sf.category_id = cat.id
          ),

          'category_rag_status', (
            SELECT CASE
              WHEN SUM(((o.score_impact + 2.0) / 4.0) * sf.weight * cat.weight)
                   / NULLIF(SUM(sf.weight * cat.weight), 0) < 0.40 THEN 'red'
              WHEN SUM(((o.score_impact + 2.0) / 4.0) * sf.weight * cat.weight)
                   / NULLIF(SUM(sf.weight * cat.weight), 0) < 0.65 THEN 'amber'
              ELSE 'green'
            END
            FROM public.observations o
            JOIN public.schema_field sf ON sf.id = o.schema_field_id
            WHERE o.screening_id = p_screening_id
              AND sf.category_id = cat.id
          ),

          'observations', (
            SELECT jsonb_agg(
              jsonb_build_object(
                'id',                      o.id,
                'observation_type',        o.observation_type,
                'name',                    o.name,
                'observation_description', o.observation_description,
                'gap_description',         o.gap_description,
                'source_reference',        o.source_reference,
                'is_gap',                  o.is_gap,
                'confidence',              o.confidence,
                'score_impact',            o.score_impact,
                'created_at',              o.created_at,

                -- Sentiment RAG baseret på rå score_impact
                'sentiment_rag', CASE
                  WHEN o.score_impact <= -1 THEN 'red'
                  WHEN o.score_impact =   0 THEN 'amber'
                  ELSE                           'green'
                END,

                -- Normaliseret bidrag til samlet MAVT-score
                'score_contribution', ROUND(
                  ((o.score_impact + 2.0) / 4.0) * sf.weight * sc.weight
                , 4),

                -- Tabte point ift. perfekt observation (score_impact = +2)
                -- Høj score_drag = trækker mest ned — vigtigste tal for UX
                'score_drag', ROUND(
                  (1.0 - (o.score_impact + 2.0) / 4.0) * sf.weight * sc.weight
                , 4),

                -- score_drag som % af total mulig vægt — sammenlignelig på tværs
                'score_drag_pct', ROUND(
                  ((1.0 - (o.score_impact + 2.0) / 4.0) * sf.weight * sc.weight)
                  / NULLIF(v_total_weight, 0) * 100
                , 1),

                'document', jsonb_build_object(
                  'id',        d.id,
                  'file_name', d.file_name,
                  'doc_id',    d.doc_id
                ),

                'field', jsonb_build_object(
                  'id',             sf.id,
                  'name',           sf.name,
                  'semantic_id',    sf.semantic_id,
                  'is_required',    sf.is_required,
                  'is_dealbreaker', sf.is_dealbreaker,
                  'weight',         sf.weight,
                  'display_order',  sf.display_order
                )
              ) ORDER BY sf.display_order, o.created_at
            )
            FROM public.observations o
            JOIN public.schema_field sf      ON sf.id = o.schema_field_id
            JOIN public.schema_categories sc ON sc.id = sf.category_id
            JOIN public.documents d          ON d.id  = o.document_id
            WHERE o.screening_id = p_screening_id
              AND sc.id = cat.id
          )
        ) ORDER BY cat.display_order
      )
      FROM public.schema_categories cat
      WHERE cat.template_id = st.id
    )

  )
  INTO v_result
  FROM public.screenings s
  JOIN public.projects p          ON p.id  = s.project_id
  JOIN public.schema_templates st ON st.id = s.schema_template_id
  WHERE s.id = p_screening_id;

  RETURN v_result;
END;$function$;

CREATE OR REPLACE FUNCTION public.get_user_org_ids()
  RETURNS SETOF uuid
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
  select org_id
  from public.org_user
  where user_id = auth.uid();
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  insert into public.profiles (id, full_name, avatar_url)
  values (new.id, new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'avatar_url');
  return new;
end;
$function$;

ALTER TABLE "public"."document_parsing_jobs"
  ADD CONSTRAINT "document_parsing_jobs_document_id_fkey" FOREIGN KEY (document_id) REFERENCES public.documents(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."observations"
  ADD CONSTRAINT "observations_document_id_fkey" FOREIGN KEY (document_id) REFERENCES public.documents(id) ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE "public"."org_user"
  ADD CONSTRAINT "org_user_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;

ALTER TABLE "public"."documents"
  ADD CONSTRAINT "documents_org_id_fkey" FOREIGN KEY (org_id) REFERENCES public.organisations(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."org_user"
  ADD CONSTRAINT "org_user_org_id_fkey" FOREIGN KEY (org_id) REFERENCES public.organisations(id) ON DELETE CASCADE;

ALTER TABLE "public"."profiles"
  ADD CONSTRAINT "profiles_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;

ALTER TABLE "public"."profiles"
  ADD CONSTRAINT "profiles_last_org_id_fkey" FOREIGN KEY (last_org_id) REFERENCES public.organisations(id) ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE "public"."projects"
  ADD CONSTRAINT "projects_organisation_id_fkey" FOREIGN KEY (org_id) REFERENCES public.organisations(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."documents"
  ADD CONSTRAINT "project_documents_project_id_fkey" FOREIGN KEY (project_id) REFERENCES public.projects(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."schema_field"
  ADD CONSTRAINT "schema_field_category_id_fkey" FOREIGN KEY (category_id) REFERENCES public.schema_categories(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."schema_field"
  ADD CONSTRAINT "schema_field_created_by_fkey" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE "public"."observations"
  ADD CONSTRAINT "observations_schema_field_id_fkey" FOREIGN KEY (schema_field_id) REFERENCES public.schema_field(id) ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE "public"."schema_templates"
  ADD CONSTRAINT "schema_templates_org_id_fkey" FOREIGN KEY (org_id) REFERENCES public.organisations(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."schema_categories"
  ADD CONSTRAINT "schema_categories_template_id_fkey" FOREIGN KEY (template_id) REFERENCES public.schema_templates(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."screening_documents"
  ADD CONSTRAINT "screening_documents_document_id_fkey" FOREIGN KEY (document_id) REFERENCES public.documents(id);

ALTER TABLE "public"."screenings"
  ADD CONSTRAINT "screenings_created_by_fkey" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE "public"."observations"
  ADD CONSTRAINT "observations_screening_id_fkey" FOREIGN KEY (screening_id) REFERENCES public.screenings(id) ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE "public"."screening_documents"
  ADD CONSTRAINT "screening_documents_screening_id_fkey" FOREIGN KEY (screening_id) REFERENCES public.screenings(id);

ALTER TABLE "public"."screenings"
  ADD CONSTRAINT "screenings_project_id_fkey" FOREIGN KEY (project_id) REFERENCES public.projects(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."screenings"
  ADD CONSTRAINT "screenings_schema_template_id_fkey" FOREIGN KEY (schema_template_id) REFERENCES public.schema_templates(id) ON UPDATE CASCADE ON DELETE SET NULL;

CREATE INDEX org_user_org_id_idx ON public.org_user USING btree (org_id);

CREATE INDEX org_user_user_id_idx ON public.org_user USING btree (user_id);

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_new_user();

CREATE POLICY "users can only create documents in their organisations" ON "public"."documents"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((org_id IN ( SELECT public.get_user_org_ids() AS get_user_org_ids)));

CREATE POLICY "users can only see documents in their organisations" ON "public"."documents"
  FOR SELECT
  TO PUBLIC
  USING ((org_id IN ( SELECT public.get_user_org_ids() AS get_user_org_ids)));

CREATE POLICY "users can delete observations in their screenings" ON "public"."observations"
  FOR DELETE
  TO PUBLIC
  USING ((screening_id IN ( SELECT s.id
   FROM ((public.screenings s
     JOIN public.projects p ON ((p.id = s.project_id)))
     JOIN public.org_user ou ON ((ou.org_id = p.org_id)))
  WHERE (ou.user_id = auth.uid()))));

CREATE POLICY "users can insert observations in their screenings" ON "public"."observations"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((screening_id IN ( SELECT s.id
   FROM ((public.screenings s
     JOIN public.projects p ON ((p.id = s.project_id)))
     JOIN public.org_user ou ON ((ou.org_id = p.org_id)))
  WHERE (ou.user_id = auth.uid()))));

CREATE POLICY "users can only see observations in their screenings" ON "public"."observations"
  FOR SELECT
  TO PUBLIC
  USING ((screening_id IN ( SELECT screening.id
   FROM (public.screenings screening
     JOIN public.projects project ON ((project.id = screening.project_id)))
  WHERE (project.org_id IN ( SELECT public.get_user_org_ids() AS get_user_org_ids)))));

CREATE POLICY "users can update observations in their screenings" ON "public"."observations"
  FOR UPDATE
  TO PUBLIC
  USING ((screening_id IN ( SELECT s.id
   FROM ((public.screenings s
     JOIN public.projects p ON ((p.id = s.project_id)))
     JOIN public.org_user ou ON ((ou.org_id = p.org_id)))
  WHERE (ou.user_id = auth.uid()))));

CREATE POLICY "users can only see members of their organisations" ON "public"."org_user"
  FOR SELECT
  TO PUBLIC
  USING ((org_id IN ( SELECT public.get_user_org_ids() AS get_user_org_ids)));

CREATE POLICY "users can only see their own organisations" ON "public"."organisations"
  FOR SELECT
  TO PUBLIC
  USING ((id IN ( SELECT public.get_user_org_ids() AS get_user_org_ids)));

CREATE POLICY "Public profiles are viewable by everyone." ON "public"."profiles"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "Users can insert their own profile." ON "public"."profiles"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((( SELECT auth.uid() AS uid) = id));

CREATE POLICY "Users can update own profile." ON "public"."profiles"
  FOR UPDATE
  TO PUBLIC
  USING ((( SELECT auth.uid() AS uid) = id));

CREATE POLICY "users can only see their own profile" ON "public"."profiles"
  FOR SELECT
  TO PUBLIC
  USING ((id = auth.uid()));

CREATE POLICY "users can only update their own profile" ON "public"."profiles"
  FOR UPDATE
  TO PUBLIC
  USING ((id = auth.uid()));

CREATE POLICY "users can only create projects in their organisations" ON "public"."projects"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((org_id IN ( SELECT public.get_user_org_ids() AS get_user_org_ids)));

CREATE POLICY "users can only delete projects in their organisations" ON "public"."projects"
  FOR DELETE
  TO PUBLIC
  USING ((org_id IN ( SELECT public.get_user_org_ids() AS get_user_org_ids)));

CREATE POLICY "users can only see projects in their organisations" ON "public"."projects"
  FOR SELECT
  TO PUBLIC
  USING ((org_id IN ( SELECT public.get_user_org_ids() AS get_user_org_ids)));

CREATE POLICY "users can only update projects in their organisations" ON "public"."projects"
  FOR UPDATE
  TO PUBLIC
  USING ((org_id IN ( SELECT public.get_user_org_ids() AS get_user_org_ids)));

CREATE POLICY "Users can view categories of their org templates" ON "public"."schema_categories"
  FOR SELECT
  TO PUBLIC
  USING ((EXISTS ( SELECT 1
   FROM (public.schema_templates st
     JOIN public.org_user ou ON ((ou.org_id = st.org_id)))
  WHERE ((st.id = schema_categories.template_id) AND (ou.user_id = auth.uid())))));

CREATE POLICY "users can only insert schema templates in their organisations" ON "public"."schema_templates"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((org_id IN ( SELECT public.get_user_org_ids() AS get_user_org_ids)));

CREATE POLICY "users can only see templates in their organisations" ON "public"."schema_templates"
  FOR SELECT
  TO PUBLIC
  USING ((org_id IN ( SELECT public.get_user_org_ids() AS get_user_org_ids)));

CREATE POLICY "users can only see screenings in their projects" ON "public"."screenings"
  FOR SELECT
  TO PUBLIC
  USING ((project_id IN ( SELECT projects.id
   FROM public.projects
  WHERE (projects.org_id IN ( SELECT public.get_user_org_ids() AS get_user_org_ids)))));

CREATE POLICY "Anyone can upload an avatar." ON "storage"."objects"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((bucket_id = 'avatars'::text));

CREATE POLICY "Avatar images are publicly accessible." ON "storage"."objects"
  FOR SELECT
  TO PUBLIC
  USING ((bucket_id = 'avatars'::text));

CREATE POLICY "Users can read their org files 19fqqs2_0" ON "storage"."objects"
  FOR SELECT
  TO "authenticated"
  USING (((bucket_id = 'project_documents'::text) AND ((storage.foldername(name))[1] IN ( SELECT (org_user.org_id)::text AS org_id
   FROM public.org_user
  WHERE (org_user.user_id = auth.uid())))));

CREATE POLICY "Users can upload to their org 19fqqs2_0" ON "storage"."objects"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (((bucket_id = 'project_documents'::text) AND ((storage.foldername(name))[1] IN ( SELECT (org_user.org_id)::text AS org_id
   FROM public.org_user
  WHERE (org_user.user_id = auth.uid())))));

